/* Record-based draft tracker. No unplayed outcomes or pick ownership assumed. */
function draftRanking(games,teams,selections={}){const records=Object.fromEntries(teams.map(t=>[t,{w:0,l:0,t:0,n:0}]));for(const g of games){const v=g.done?(g.hs===g.as_?.5:g.hs>g.as_?1:0):selections[g.id];if(![0,.5,1].includes(v))continue;for(const t of [g.h,g.a]){const r=records[t];r.n++;if(v===.5)r.t++;else if((v===1)===(t===g.h))r.w++;else r.l++}}const rows=teams.map(team=>{const r=records[team];let wins=0,total=0;for(const g of games){if(g.h!==team&&g.a!==team)continue;const opp=records[g.h===team?g.a:g.h];wins+=opp.w+opp.t*.5;total+=opp.n}return {team,...r,pct:r.n?(r.w+r.t*.5)/r.n:.5,sos:total?wins/total:.5}}).sort((a,b)=>a.pct-b.pct||a.sos-b.sos||a.team.localeCompare(b.team));for(let i=0;i<rows.length;i++){let lo=i,hi=i;while(lo>0&&Math.abs(rows[lo-1].pct-rows[i].pct)<1e-12&&Math.abs(rows[lo-1].sos-rows[i].sos)<1e-12)lo--;while(hi+1<rows.length&&Math.abs(rows[hi+1].pct-rows[i].pct)<1e-12&&Math.abs(rows[hi+1].sos-rows[i].sos)<1e-12)hi++;rows[i].rank=lo===hi?String(i+1):(lo+1)+'–'+(hi+1)}return rows}
function draftOwners(rows){const owners=Object.fromEntries(rows.map(r=>[r.team,{owner:r.team,note:''}]));for(const [original,owner,note] of [['IND','NYJ','Sauce Gardner trade'],['LAR','CLE','Myles Garrett trade'],['CHI','TEN','Jeffery Simmons trade'],['JAX','PHI','Jordan Davis trade']])if(owners[original])owners[original]={owner,note};const dal=rows.find(r=>r.team==='DAL'),gb=rows.find(r=>r.team==='GB');if(dal&&gb){const tied=Math.abs(dal.pct-gb.pct)<1e-12&&Math.abs(dal.sos-gb.sos)<1e-12;if(tied){for(const t of ['DAL','GB'])owners[t]={owner:null,note:'NYJ / DAL pending tiebreaker; Jets receive earlier pick'}}else{const earlier=rows.indexOf(dal)<rows.indexOf(gb)?'DAL':'GB';for(const t of ['DAL','GB'])owners[t]={owner:t===earlier?'NYJ':'DAL',note:t===earlier?'Quinnen Williams: earlier of DAL/GB (projected)':'Dallas retains later DAL/GB pick (projected)'}}}return owners}
if(typeof module!=='undefined')module.exports={draftRanking,draftOwners};
if(typeof document!=='undefined')(()=>{const section=document.createElement('section');section.id='draftOrder';section.className='draft-order hub-card';section.innerHTML='<div class="hub-stats-head"><div><span class="eyebrow">2027 DRAFT TRACKER</span><h2>Where your picks move the draft.</h2></div><a href="#draftTable">View order ↓</a></div><p id="draftStatus" role="status">Loading records…</p><p class="muted">Record-based order, not official draft slots. Lowest win percentage first; weaker full-season opponent schedule breaks record ties. First-round ownership verified November 20, 2026. Playoff finishes are not included. The Jets receive the earlier Dallas/Green Bay pick; that assignment is projected from this record-based order. Equal record and schedule strength are shown as tied ranges.</p><div class="table-wrap"><table id="draftTable"><thead><tr><th>With picks</th><th>Pick owner</th><th>Original team</th><th>Trade / condition</th><th>Current order</th><th>Current record</th><th>With picks</th><th>Schedule strength</th></tr></thead><tbody id="draftRows"></tbody></table></div><p class="muted">Trade sources: <a href="https://www.prosportstransactions.com/football/DraftTrades/Years/2027.htm" target="_blank" rel="noopener">2027 transaction ledger</a>. Ownership is a verified snapshot; new trades require an update.</p>';document.getElementById('mainContent').insertBefore(section,document.getElementById('mainContent').lastElementChild);
function renderDraft(){if(!data)return;const teams=Object.keys(meta),current=draftRanking(data.games,teams),scenario=draftRanking(data.games,teams,picks),map=Object.fromEntries(current.map(r=>[r.team,r]));const owners=draftOwners(scenario);const count=Object.keys(picks).length;document.getElementById('draftStatus').textContent=count?count+' selected result'+(count===1?'':'s')+' included. Clear picks to return to current records.':'Current order from completed games. Pick winners in the simulator to change it.';const body=document.getElementById('draftRows');body.replaceChildren();for(const r of scenario){const tr=document.createElement('tr');if(r.team===focus||owners[r.team].owner===focus)tr.className='focused';const base=map[r.team],record=x=>x.w+'–'+x.l+(x.t?'–'+x.t:'');for(const text of [r.rank,owners[r.team].owner?meta[owners[r.team].owner][0]:'Jets / Cowboys — unresolved',meta[r.team][0],owners[r.team].note||'Own pick',base.rank,record(base),record(r),r.sos.toFixed(3)]){const td=document.createElement('td');td.textContent=text;tr.append(td)}body.append(tr)}}document.addEventListener('lab:state',renderDraft);document.addEventListener('lab:update',renderDraft);renderDraft();})();
